def check(args, got, expected):
    s, t = args
    from collections import Counter
    t_counts = Counter(t)
    if got == "":
        # Check if really impossible
        for i in range(len(s)):
            for j in range(i + len(t), len(s) + 1):
                sub = s[i:j]
                sc = Counter(sub)
                if all(sc[k] >= v for k, v in t_counts.items()):
                    return False
        return True

    sc = Counter(got)
    if not all(sc[k] >= v for k, v in t_counts.items()):
        return False

    # Check length is minimal
    # We can run a small search or verify it's valid and matches expected length
    return len(got) == len(expected)

